    static let day = 86400000.0, sessionCount = 40, sessionGapDays = 10, sessionTimes = ["11:33", "07:10", "18:45", "12:05", "19:20", "06:55", "17:30"]
    static let months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"], weekdays = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
    static func date(_ session: String) -> Date { var c = Calendar(identifier: .gregorian); c.timeZone = TimeZone(secondsFromGMT: 0)!; let p = session.prefix(10).split(separator: "-").map { Int($0)! }; return c.date(from: DateComponents(year: p[0], month: p[1], day: p[2]))! }
    static func parts(_ session: String) -> DateComponents { var c = Calendar(identifier: .gregorian); c.timeZone = TimeZone(secondsFromGMT: 0)!; return c.dateComponents([.month, .day, .weekday], from: date(session)) }
    static func rangeStart(_ sessions: [String], _ range: MetricDropdownLineScrubRange) -> Int { guard let days = range.days, !sessions.isEmpty else { return 0 }; let from = date(sessions.last!).addingTimeInterval(-Double(days) * day / 1000); return sessions.firstIndex { date($0) >= from } ?? sessions.count - 1 }
    static func shortDate(_ session: String) -> String { let c = parts(session); return "\(c.day!) \(months[c.month! - 1].prefix(3))" }
    static func longDate(_ session: String) -> String { let c = parts(session), clock = session.dropFirst(11).prefix(5); return "\(clock) · \(weekdays[c.weekday! - 1]) \(c.day!) \(months[c.month! - 1])" }
    static func axisValue(_ value: Double) -> String { let v = floor(value * 10 + 0.5) / 10; return v == floor(v) ? String(Int(v)) : String(format: "%.1f", v) }
    static func layoutPoints(_ metric: MetricDropdownLineScrubMetric, _ start: Int, _ slots: Int) -> [Double] { let values = Array(metric.values.dropFirst(start)), count = values.count; var p: [Double] = []; for slot in 0..<slots { let i = count <= 1 ? 0 : Int(floor(Double(slot * (count - 1)) / Double(max(1, slots - 1)) + 0.5)); p += [count <= 1 ? 0.5 : Double(i) / Double(count - 1), min(1, max(0, (values[i] - metric.min) / (metric.max - metric.min)))] }; return p }
    static func format(_ value: Double, _ decimals: Int) -> String { let bits = abs(value).bitPattern, e = Int((bits >> 52) & 0x7ff) - 1023 - 52, scale = UInt64(pow(10, Double(decimals))), n = ((bits & 0x000fffffffffffff) | (UInt64(1) << 52)) * scale; let units: UInt64; if e >= 0 { units = n << e } else { let shift = -e; units = shift >= 64 ? 0 : (n >> shift) + ((n & ((UInt64(1) << shift) - 1)) >= (UInt64(1) << (shift - 1)) ? 1 : 0) }; let sign = value < 0 ? "-" : ""; return sign + String(units / scale) + (decimals == 0 ? "" : "." + String(format: "%0*d", decimals, Int(units % scale))) }
}
